select public.importa_quiz('nodejs', $j$[
  {"livello":"L1","testo":"Quale comando esegue un file JavaScript con Node?","spiegazione":"node nome-file.js avvia il file con il runtime Node.","opzioni":["node file.js","npm file.js","run node file.js","node --run file.js"],"corretta":0},
  {"livello":"L1","testo":"Quale oggetto espone le variabili d'ambiente?","spiegazione":"process.env contiene le variabili del processo, incluse quelle caricate da .env.","opzioni":["process.env","global.env","os.env","env.process"],"corretta":0},
  {"livello":"L1","testo":"Quale modulo nativo legge e scrive file?","spiegazione":"fs espone readFile, writeFile e le varianti sincrone, da evitare nel server.","opzioni":["fs","path","http","os"],"corretta":0},
  {"livello":"L1","testo":"Quale modulo nativo crea un server HTTP?","spiegazione":"http.createServer gestisce richieste e risposte; Express vi si appoggia sopra.","opzioni":["http","net","fs","url"],"corretta":0},
  {"livello":"L1","testo":"Quale file descrive un progetto npm?","spiegazione":"package.json contiene nome, script e dipendenze del progetto.","opzioni":["package.json","node.json","project.json","deps.json"],"corretta":0},
  {"livello":"L1","testo":"Quale comando installa le dipendenze dichiarate?","spiegazione":"npm install legge package.json e popola node_modules.","opzioni":["npm install","npm run","npm init","npm publish"],"corretta":0},
  {"livello":"L1","testo":"Quale proprietà contiene gli argomenti della riga di comando?","spiegazione":"process.argv è un array: i primi due elementi sono il percorso di node e del file.","opzioni":["process.argv","process.args","process.command","process.input"],"corretta":0},
  {"livello":"L1","testo":"Quale sistema di moduli usa require?","spiegazione":"require appartiene a CommonJS; import/export è il sistema ES Modules.","opzioni":["CommonJS","ES Modules","AMD","UMD"],"corretta":0},

  {"livello":"L2","testo":"Qual è la differenza tra dependencies e devDependencies?","spiegazione":"Le prime servono a runtime, le seconde solo per sviluppo e test.","opzioni":["dependencies serve a runtime, devDependencies allo sviluppo","Sono identiche","devDependencies serve in produzione","dependencies serve solo ai test"],"corretta":0},
  {"livello":"L2","testo":"Cosa fa npm ci rispetto a npm install?","spiegazione":"Installa esattamente le versioni del lockfile, in modo riproducibile e più adatto alla CI.","opzioni":["Installa esattamente le versioni del lockfile","Aggiorna tutte le dipendenze","Crea il package.json","Pubblica il pacchetto"],"corretta":0},
  {"livello":"L2","testo":"A cosa serve module.exports?","spiegazione":"Esporta valori da un modulo CommonJS, rendendoli disponibili a chi fa require.","opzioni":["Esporta valori dal modulo","Importa un modulo","Definisce una classe","Avvia il server"],"corretta":0},
  {"livello":"L2","testo":"Cosa fa path.join?","spiegazione":"Unisce i segmenti usando il separatore corretto del sistema operativo.","opzioni":["Unisce segmenti con il separatore corretto","Legge un file","Crea una cartella","Normalizza l'URL"],"corretta":0},
  {"livello":"L2","testo":"Cosa distingue fs.readFile da fs.readFileSync?","spiegazione":"readFile è asincrono e non blocca l'event loop; readFileSync blocca il thread.","opzioni":["readFile è asincrono e non blocca il thread","readFileSync è asincrono","Sono identici","readFile legge solo JSON"],"corretta":0},
  {"livello":"L2","testo":"Cosa fa process.exit(1)?","spiegazione":"Termina il processo con codice 1, convenzionalmente usato per gli errori.","opzioni":["Termina il processo con codice di errore","Riavvia il server","Lancia un'eccezione","Chiude una connessione"],"corretta":0},
  {"livello":"L2","testo":"Cosa indica un codice di uscita 0?","spiegazione":"Indica successo: la convenzione è 0 per esito positivo, diverso da 0 per errore.","opzioni":["Successo","Errore generico","Timeout","Segnale interrotto"],"corretta":0},
  {"livello":"L2","testo":"A cosa serve dotenv?","spiegazione":"Carica le variabili da un file .env in process.env durante lo sviluppo.","opzioni":["Carica variabili da .env in process.env","Crea il database","Avvia il server","Minifica il codice"],"corretta":0},

  {"livello":"L3","testo":"Perché il file .env non va committato?","spiegazione":"Contiene segreti come chiavi e password: va escluso da Git e documentato con .env.example.","opzioni":["Perché contiene segreti come chiavi e password","Perché è troppo grande","Perché Node non lo legge da Git","Perché rallenta l'avvio"],"corretta":0},
  {"livello":"L3","testo":"Perché un calcolo CPU-bound va spostato in un worker?","spiegazione":"Il worker ha un thread separato: l'event loop principale resta libero per le richieste.","opzioni":["Per lasciare libero l'event loop principale","Per usare meno memoria","Per evitare le Promise","Per scrivere su disco"],"corretta":0},
  {"livello":"L3","testo":"Perché gli stream sono utili per file grandi?","spiegazione":"Elaborano i dati a pezzi con memoria costante, invece di caricare tutto in RAM.","opzioni":["Elaborano a pezzi con memoria costante","Sono più semplici da leggere","Comprimono automaticamente","Evitano il filesystem"],"corretta":0},
  {"livello":"L3","testo":"Perché conviene gestire l'evento unhandledRejection?","spiegazione":"Una Promise rifiutata senza catch può terminare il processo: il log esplicito aiuta a diagnosticare.","opzioni":["Per evitare crash silenziosi e diagnosticare l'errore","Per velocizzare le Promise","Per convertire in callback","Per chiudere il socket"],"corretta":0},
  {"livello":"L3","testo":"Perché evitare operazioni sincrone sui file nel server?","spiegazione":"Bloccano l'event loop: durante la lettura il server non risponde alle altre richieste.","opzioni":["Bloccano l'event loop e fermano le risposte","Consumano troppa CPU","Non funzionano su Linux","Richiedono permessi root"],"corretta":0},
  {"livello":"L3","testo":"Perché si versiona package-lock.json?","spiegazione":"Fissa l'albero esatto delle dipendenze e rende le build riproducibili su ogni macchina.","opzioni":["Per avere installazioni riproducibili","Per ridurre il peso del repository","Per evitare npm install","Per pubblicare su npm"],"corretta":0},
  {"livello":"L3","testo":"Perché separare l'app Express dall'avvio con listen?","spiegazione":"Consente di importare l'app nei test senza aprire una porta reale.","opzioni":["Per testare l'app senza aprire una porta","Per usare meno memoria","Per abilitare HTTPS","Per evitare i middleware"],"corretta":0},
  {"livello":"L3","testo":"Perché il path traversal è pericoloso quando si servono file?","spiegazione":"Un percorso con ../ può uscire dalla directory consentita e leggere file di sistema.","opzioni":["Un percorso con ../ può uscire dalla directory consentita","Rallenta il server","Rompe il MIME type","Impedisce il caching"],"corretta":0},

  {"livello":"L4","testo":"Perché usare un cluster o PM2 su più core?","spiegazione":"Node sfrutta un core per processo: più istanze distribuiscono il carico sugli altri core.","opzioni":["Per sfruttare più core della CPU","Per ridurre le dipendenze","Per evitare il garbage collector","Per comprimere le risposte"],"corretta":0},
  {"livello":"L4","testo":"Perché NODE_ENV non è un meccanismo di sicurezza?","spiegazione":"È solo una convenzione letta dal codice: chiunque può avviare il processo con un valore diverso.","opzioni":["È solo una convenzione, non un controllo di sicurezza","È protetto dal sistema operativo","Crittografa le variabili","Disattiva i log"],"corretta":0},
  {"livello":"L4","testo":"Perché serve un graceful shutdown?","spiegazione":"Va smesso di accettare richieste, completate quelle in corso e chiusi database e code prima di uscire.","opzioni":["Per chiudere richieste e connessioni senza perdere lavoro","Per riavviare più velocemente","Per liberare la cache DNS","Per evitare il logging"],"corretta":0},
  {"livello":"L4","testo":"Perché limitare la dimensione del body JSON?","spiegazione":"Un payload enorme consuma memoria e può saturare il processo: express.json({ limit }) lo impedisce.","opzioni":["Un payload enorme consuma memoria e può saturare il processo","Per rispettare i tipi MIME","Per evitare il CORS","Per velocizzare il TLS"],"corretta":0}
]$j$::jsonb);

select public.importa_quiz('mysql', $j$[
  {"livello":"L1","testo":"Quale vincolo identifica univocamente una riga?","spiegazione":"PRIMARY KEY impone unicità e non null sulla colonna o combinazione scelta.","opzioni":["PRIMARY KEY","UNIQUE","INDEX","FOREIGN KEY"],"corretta":0},
  {"livello":"L1","testo":"Quale istruzione aggiunge righe a una tabella?","spiegazione":"INSERT INTO aggiunge una o più righe con i valori indicati.","opzioni":["INSERT","UPDATE","SELECT","ALTER"],"corretta":0},
  {"livello":"L1","testo":"Quale istruzione modifica righe esistenti?","spiegazione":"UPDATE cambia i valori delle righe che soddisfano la clausola WHERE.","opzioni":["UPDATE","INSERT","DELETE","CREATE"],"corretta":0},
  {"livello":"L1","testo":"Quale clausola ordina i risultati?","spiegazione":"ORDER BY specifica colonne e direzione (ASC o DESC).","opzioni":["ORDER BY","GROUP BY","WHERE","HAVING"],"corretta":0},
  {"livello":"L1","testo":"Quale clausola limita il numero di righe restituite?","spiegazione":"LIMIT n restituisce al massimo n righe e si combina con OFFSET per la paginazione.","opzioni":["LIMIT","TOP","FETCH","SIZE"],"corretta":0},
  {"livello":"L1","testo":"Quale funzione conta le righe?","spiegazione":"COUNT(*) conta le righe del gruppo o della tabella.","opzioni":["COUNT","SUM","AVG","MAX"],"corretta":0},
  {"livello":"L1","testo":"Quale tipo memorizza testo lungo?","spiegazione":"TEXT gestisce testi lunghi; VARCHAR ha un limite dichiarato.","opzioni":["TEXT","CHAR","INT","DATE"],"corretta":0},
  {"livello":"L1","testo":"Con quale tipo si rappresenta un valore vero o falso?","spiegazione":"MySQL non ha un boolean nativo: BOOLEAN è un alias di TINYINT(1).","opzioni":["BOOLEAN","BIT","CHAR(1)","ENUM"],"corretta":0},

  {"livello":"L2","testo":"Qual è la differenza tra INNER JOIN e LEFT JOIN?","spiegazione":"INNER restituisce solo le righe con corrispondenza, LEFT tutte quelle di sinistra anche senza corrispondenza.","opzioni":["INNER solo le corrispondenze, LEFT tutte le righe di sinistra","LEFT solo le corrispondenze, INNER tutte","Sono identici","LEFT elimina i duplicati"],"corretta":0},
  {"livello":"L2","testo":"Cosa fa DISTINCT?","spiegazione":"Rimuove le righe duplicate dal risultato della SELECT.","opzioni":["Rimuove le righe duplicate","Ordina i risultati","Conta le righe","Filtra i null"],"corretta":0},
  {"livello":"L2","testo":"Cosa fa GROUP BY?","spiegazione":"Raggruppa le righe con gli stessi valori, permettendo le aggregazioni per gruppo.","opzioni":["Raggruppa le righe per valori uguali","Ordina per colonna","Elimina i duplicati","Crea una vista"],"corretta":0},
  {"livello":"L2","testo":"Cosa garantisce una FOREIGN KEY?","spiegazione":"Che il valore referenziato esista nella tabella padre: è integrità referenziale.","opzioni":["Che il valore referenziato esista nella tabella padre","Che la colonna sia unica","Che la colonna non sia null","Che l'indice sia usato"],"corretta":0},
  {"livello":"L2","testo":"Cosa fa ON DELETE CASCADE?","spiegazione":"Eliminando la riga padre vengono eliminate automaticamente le righe figlie collegate.","opzioni":["Elimina le righe figlie collegate","Impedisce l'eliminazione","Imposta il valore a null","Archivia le righe"],"corretta":0},
  {"livello":"L2","testo":"Qual è la differenza tra CHAR e VARCHAR?","spiegazione":"CHAR ha lunghezza fissa con padding, VARCHAR è a lunghezza variabile.","opzioni":["CHAR è a lunghezza fissa, VARCHAR variabile","VARCHAR è a lunghezza fissa, CHAR variabile","Sono identici","CHAR accetta solo numeri"],"corretta":0},
  {"livello":"L2","testo":"Cosa fa COALESCE?","spiegazione":"Restituisce il primo argomento non null, utile per i valori di default.","opzioni":["Restituisce il primo valore non null","Somma i valori","Converte in stringa","Ordina i null in fondo"],"corretta":0},

  {"livello":"L3","testo":"Perché un indice accelera le letture ma rallenta le scritture?","spiegazione":"Ogni INSERT, UPDATE e DELETE deve aggiornare anche la struttura dell'indice.","opzioni":["Ogni scrittura deve aggiornare anche l'indice","Gli indici bloccano le transazioni","Gli indici occupano CPU in lettura","Gli indici disabilitano le foreign key"],"corretta":0},
  {"livello":"L3","testo":"Perché LIKE con il carattere jolly iniziale non usa l'indice?","spiegazione":"Senza prefisso fisso il motore non può navigare l'albero e deve scandire le righe.","opzioni":["Senza prefisso fisso deve scandire tutte le righe","LIKE è deprecato","L'indice vale solo per i numeri","Il jolly disabilita la collation"],"corretta":0},
  {"livello":"L3","testo":"Perché SELECT * è sconsigliato in produzione?","spiegazione":"Legge colonne inutili e impedisce la copertura dell'indice, aumentando I/O e traffico.","opzioni":["Legge colonne inutili e impedisce la copertura dell'indice","Non funziona con le join","Richiede permessi speciali","Elimina le righe duplicate"],"corretta":0},
  {"livello":"L3","testo":"Cosa garantisce l'atomicità di una transazione?","spiegazione":"O tutte le operazioni vengono confermate, o nessuna: non restano stati intermedi.","opzioni":["O tutte le operazioni vengono confermate o nessuna","Che le query siano veloci","Che i dati siano cifrati","Che le foreign key siano attive"],"corretta":0},
  {"livello":"L3","testo":"Perché il livello di isolamento conta?","spiegazione":"Determina quali anomalie sono possibili, come letture non ripetibili o phantom read.","opzioni":["Determina quali anomalie di lettura sono possibili","Cambia la sintassi SQL","Definisce i permessi utente","Imposta il charset"],"corretta":0},
  {"livello":"L3","testo":"Perché normalizzare i dati?","spiegazione":"Riduce ridondanza e anomalie di aggiornamento, mantenendo una sola fonte per ogni fatto.","opzioni":["Riduce ridondanza e anomalie di aggiornamento","Aumenta il numero di join","Elimina gli indici","Riduce la sicurezza"],"corretta":0},
  {"livello":"L3","testo":"Quando ha senso denormalizzare?","spiegazione":"Quando le letture sono frequenti e i join costosi: si duplica un dato accettando il rischio di disallineamento.","opzioni":["Quando le letture sono frequenti e i join costosi","Sempre, per risparmiare spazio","Solo nelle tabelle senza chiave","Mai, viola ACID"],"corretta":0},
  {"livello":"L3","testo":"A cosa serve EXPLAIN?","spiegazione":"Mostra il piano di esecuzione: indici usati, ordine delle join e righe stimate.","opzioni":["Mostra il piano di esecuzione della query","Esegue la query due volte","Crea un indice","Mostra lo schema"],"corretta":0},

  {"livello":"L4","testo":"Come va ordinato un indice composito rispetto alle query?","spiegazione":"Conta il prefisso sinistro: le colonne usate nei filtri vanno prima, secondo l'ordine reale delle query.","opzioni":["Con le colonne dei filtri prima, secondo l'ordine delle query","In ordine alfabetico","Con la chiave primaria sempre ultima","Con le colonne più lunghe prima"],"corretta":0},
  {"livello":"L4","testo":"Perché le transazioni lunghe peggiorano le prestazioni?","spiegazione":"Mantengono lock e versioni delle righe, bloccando altre transazioni e gonfiando l'undo log.","opzioni":["Mantengono lock e versioni delle righe bloccando gli altri","Consumano solo CPU","Impediscono le letture","Disattivano gli indici"],"corretta":0},
  {"livello":"L4","testo":"Perché la paginazione con OFFSET alto è lenta?","spiegazione":"Il motore legge e scarta tutte le righe precedenti: la chiave di paginazione (seek) evita lo spreco.","opzioni":["Il motore legge e scarta tutte le righe precedenti","OFFSET blocca la tabella","OFFSET richiede una transazione","LIMIT non funziona con OFFSET"],"corretta":0}
]$j$::jsonb);
